import 'dotenv/config';
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { createClient } from '@supabase/supabase-js';
import { buildApprovedCatalogueAsset } from '../backend/lib/assetPipeline.js';
import { SupabaseObjectStorageAdapter } from '../backend/lib/objectStorage.js';

const REF='oakdbbzdqwurpjnoqhmu', VERSION='d560cd01-de2a-4713-9518-b967fb4c5ac9', SOURCE_ID='aeb43aa5-a6ec-4b99-93da-beeab7f92710';
const m=JSON.parse(readFileSync(process.env.STACKR_POKEDATA_GAP_MANIFEST??'deploy/manifests/pokedata-gap-art-20260910.json','utf8'));
const apply=process.env.STACKR_POKEDATA_GAP_APPLY==='true', out=process.env.STACKR_POKEDATA_GAP_EVIDENCE_PATH;
const clean=x=>String(x??'').trim()||null;
const ready=a=>a?.permission_status==='approved'&&a?.rights_status==='approved'&&a?.publicly_servable===true&&a?.asset_visibility==='public_catalogue'&&a?.retention_status==='active'&&!a?.deleted_at&&['supabase_storage','s3_compatible'].includes(a?.storage_provider)&&a?.storage_key&&Array.isArray(a?.derivative_list)&&['card-grid','search-result','detail-page'].every(r=>a.derivative_list.some(x=>x?.role===r));
function save(v){mkdirSync(path.dirname(out),{recursive:true});writeFileSync(out,JSON.stringify(v,null,2)+'\n',{mode:0o600});}
async function bytes(url){const u=new URL(url);if(u.protocol!=='https:'||u.hostname!=='pokemoncardimages.pokedata.io')throw Error('source_url_guard');const r=await fetch(u,{signal:AbortSignal.timeout(30000)});if(!r.ok)throw Error(`source_fetch_${r.status}`);const mime=clean(r.headers.get('content-type'))?.split(';')[0].toLowerCase();if(!['image/jpeg','image/png','image/webp'].includes(mime))throw Error(`source_mime_invalid:${mime}`);return {body:Buffer.from(await r.arrayBuffer()),mime};}
class MemoryStorage { constructor(){this.id='memory_dry_run';this.objects=new Map()} async putObject(i){this.objects.set(`${i.bucket}/${i.key}`,Buffer.from(i.body));return {provider:this.id,bucket:i.bucket,key:i.key,path:i.key}} }
class ReceiptStorage { constructor(inner,receipt){this.id=inner.id;this.inner=inner;this.receipt=receipt} async putObject(i){try{const current=await this.inner.getObject(i.bucket,i.key,{maxBytes:25*1024*1024});if(!Buffer.from(current).equals(Buffer.from(i.body)))throw Error(`storage_key_content_conflict:${i.key}`);return {provider:this.id,bucket:i.bucket,key:i.key,path:i.key,duplicate:true}}catch(e){if(!/not found|object.*not|404/i.test(String(e?.message??e)))throw e;this.receipt.rollback.pendingObjectKey=i.key;save({...this.receipt,phase:'object_upload_pending'});const v=await this.inner.putObject(i);this.receipt.rollback.insertedObjectKeys.push(i.key);delete this.receipt.rollback.pendingObjectKey;save({...this.receipt,phase:'object_uploaded'});return v}} }
if(m.contract!=='pokedata-gap-art-20260910'||m.candidates?.length!==82||new Set(m.candidates.map(x=>x.variantId)).size!==82)throw Error('frozen82_manifest_invalid');
if(new URL(process.env.SUPABASE_URL??'').hostname!==`${REF}.supabase.co`||!clean(process.env.SUPABASE_SECRET_KEY)||!out)throw Error('production_credentials_required');
if(apply&&process.env.STACKR_POKEDATA_GAP_CONFIRMATION!=='MATERIALIZE 82 VERIFIED POKEDATA ART')throw Error('apply_confirmation_required');
const db=createClient(process.env.SUPABASE_URL,process.env.SUPABASE_SECRET_KEY,{auth:{persistSession:false}}), storage=new SupabaseObjectStorageAdapter(db);
const receipt={contract:m.contract,target:'production',apply,startedAt:new Date().toISOString(),items:[],rollback:{preApplyAssets:[],insertedObjectKeys:[]}};
try {
 const ids=m.candidates.map(x=>x.variantId);
 const {data:version,error:ve}=await db.schema('catalog').from('catalogue_versions').select('id,status,language_code,deprecated_at').eq('id',VERSION).maybeSingle();if(ve||version?.status!=='published'||version.language_code!=='ja'||version.deprecated_at)throw Error('published_version_not_current');
 const {data:members,error:me}=await db.schema('catalog').from('catalogue_version_variants').select('set_id,printing_id,variant_id,card_variants!inner(language_code,variant_code,finish_code,game_code)').eq('catalogue_version_id',VERSION).in('variant_id',ids); if(me||members?.length!==82)throw Error('production_membership_missing');
 for(const c of m.candidates){const r=members.find(x=>x.variant_id===c.variantId);if(!r||r.set_id!==m.sets[c.setCode]||r.printing_id!==c.printingId||r.card_variants.language_code!=='ja'||r.card_variants.variant_code!==c.variantCode||r.card_variants.finish_code!==c.finishCode||!r.card_variants.game_code)throw Error(`identity_drift:${c.variantId}`)}
 const {data:existing,error:ae}=await db.schema('catalog').from('assets').select('*').in('variant_id',ids).eq('asset_type','card_image').is('deprecated_at',null).is('deleted_at',null);if(ae)throw ae;
 const {data:priorLinks,error:pe}=await db.schema('catalog').from('catalogue_version_assets').select('*').eq('catalogue_version_id',VERSION).in('variant_id',ids);if(pe)throw pe;receipt.rollback.preApplyVersionLinks=priorLinks??[];
 for(const a of existing??[]){const c=m.candidates.find(x=>x.variantId===a.variant_id);if(a.printing_id!==c.printingId||(!ready(a)&&(a.source_id!==SOURCE_ID||a.original_source_url!==c.sourceUrl||a.storage_provider!=='external_reference')))throw Error(`unexpected_existing_asset:${a.id}`)}
 const grouped=new Map();for(const a of existing??[]){const rows=grouped.get(a.variant_id)??[];rows.push(a);grouped.set(a.variant_id,rows)};if([...grouped.values()].some(rows=>rows.length>1))throw Error('multiple_existing_assets_per_variant'); const map=new Map([...grouped].map(([id,rows])=>[id,rows[0]])); receipt.rollback.preApplyAssets=existing??[]; save({...receipt,phase:'preflight_complete'});
 for(const c of m.candidates){const before=map.get(c.variantId)??null, member=members.find(x=>x.variant_id===c.variantId);const item={variantId:c.variantId,printingId:c.printingId,status:'would_materialize',sourceUrl:c.sourceUrl,beforeAssetId:before?.id??null};receipt.items.push(item);save({...receipt,phase:'item_prepared'}); if(ready(before)){if(apply){const {error}=await db.schema('catalog').from('catalogue_version_assets').upsert({catalogue_version_id:VERSION,language_code:'ja',set_id:member.set_id,printing_id:c.printingId,variant_id:c.variantId,asset_id:before.id,asset_type:'card_image'},{onConflict:'catalogue_version_id,asset_id'});if(error)throw error}item.status='ready_asset_link_reconciled';save({...receipt,phase:'ready_link_reconciled'});continue} const input=await bytes(c.sourceUrl);const materializer=apply?new ReceiptStorage(storage,receipt):new MemoryStorage();const built=await buildApprovedCatalogueAsset({assetType:'card_image',buffer:input.body,mimeType:input.mime,permissionStatus:'approved',rightsStatus:'approved',sourceUrl:c.sourceUrl,sourceIdentifier:c.providerRecordId,sourceAttribution:'pokedata_japanese',storage:materializer});item.byteSize=input.body.length;item.contentSha256=built.content_sha256;if(!apply){item.derivativeKeys=built.derivative_list.map(x=>x.storageKey);continue}
   const patch={...built,game_code:member.card_variants.game_code,set_id:member.set_id,variant_id:c.variantId,printing_id:c.printingId,source_id:SOURCE_ID,url:storage.publicUrl(built.storage_bucket,built.storage_key),original_source_url:c.sourceUrl,original_source_identifier:c.providerRecordId,source_attribution:'pokedata_japanese',asset_visibility:'public_catalogue',publicly_servable:true,retention_status:'active'};
   const q=before?db.schema('catalog').from('assets').update(patch).eq('id',before.id).eq('updated_at',before.updated_at).eq('storage_provider',before.storage_provider).select('id').maybeSingle():db.schema('catalog').from('assets').insert(patch).select('id').maybeSingle(); const {data:written,error:we}=await q;if(we||!written?.id)throw Error(`optimistic_asset_write_failed:${c.variantId}`);
   item.assetId=written.id;item.status='asset_written';save({...receipt,phase:'asset_written'});
   const {error:le}=await db.schema('catalog').from('catalogue_version_assets').upsert({catalogue_version_id:VERSION,language_code:'ja',set_id:m.sets[c.setCode],printing_id:c.printingId,variant_id:c.variantId,asset_id:written.id,asset_type:'card_image'},{onConflict:'catalogue_version_id,asset_id'});if(le)throw le;
   item.status='materialized';item.assetId=written.id;item.derivativeKeys=built.derivative_list.map(x=>x.storageKey);save({...receipt,phase:'item_materialized'});
 }
 receipt.completedAt=new Date().toISOString();save({...receipt,phase:apply?'applied':'dry_run'});console.log(JSON.stringify({ok:true,apply,items:receipt.items.length,materialized:receipt.items.filter(x=>x.status==='materialized').length}));
}catch(e){receipt.failedAt=new Date().toISOString();receipt.error=e instanceof Error?e.message:String(e);save({...receipt,phase:'failed'});throw e}
